const catalogs = { en, es };
const localeKey = "kodergarden.locale";
const detectLocale = (): Locale => { const saved = sessionStorage.getItem(localeKey) ?? localStorage.getItem(localeKey); if (saved === "en" || saved === "es") return saved; return navigator.language.toLowerCase().startsWith("es") ? "es" : "en"; };
const I18nContext = createContext<{locale:Locale;setLocale:(locale:Locale)=>void;t:(key:string,values?:Values)=>string}|null>(null);
export function I18nProvider({children}:{readonly children:ReactNode}) { const [locale,setLocaleState]=useState<Locale>(detectLocale); const value=useMemo(()=>({locale,setLocale:(next:Locale)=>{sessionStorage.setItem(localeKey,next);localStorage.setItem(localeKey,next);setLocaleState(next);},t:(key:string,values:Values={})=>{let text=catalogs[locale][key]??en[key]??key; for(const [name,value] of Object.entries(values)) text=text.replaceAll(`{${name}}`,String(value)); return text;}}),[locale]); return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>; }
export const useI18n = () => { const value=useContext(I18nContext); if(!value) throw new Error("I18nProvider missing"); return value; };
export const translate = (locale:Locale,key:string,values:Values={}) => { let text=catalogs[locale][key]??en[key]??key; for(const [name,value] of Object.entries(values)) text=text.replaceAll(`{${name}}`,String(value)); return text; };
